INSERT INTO product_variants (product_id, attribute_name, attribute_value, price_delta) SELECT id, 'RAM', '32GB Unified Memory', 150.00 FROM products WHERE id > 26;
INSERT INTO product_variants (product_id, attribute_name, attribute_value, price_delta) SELECT id, 'Storage', '1TB High-Speed SSD', 250.00 FROM products WHERE id > 26;
INSERT IGNORE INTO warehouse_stocks (warehouse_id, product_id, in_stock, reserved, available, reorder_level) SELECT 1, id, 80, 5, 75, 10 FROM products WHERE id NOT IN (SELECT product_id FROM warehouse_stocks WHERE warehouse_id = 1);
INSERT IGNORE INTO warehouse_stocks (warehouse_id, product_id, in_stock, reserved, available, reorder_level) SELECT 2, id, 40, 2, 38, 5 FROM products WHERE id NOT IN (SELECT product_id FROM warehouse_stocks WHERE warehouse_id = 2);
INSERT INTO quotations (quote_number, customer_id, sales_rep_id, status, subtotal_amount, total_discount_amount, total_amount, total_cost, total_margin_amount, margin_percentage, blended_risk_score, version, portal_token, promised_delivery_date, last_activity_at, created_at)
INSERT INTO quotation_lines (quotation_id, product_id, quantity, unit_price, cost_price, discount_percent, line_total, margin_amount, line_type, subscription_plan_id, overage_points, status)
INSERT INTO approval_requests (quotation_id, status, current_stage, blended_risk_score, risk_level, explanation, created_at)
INSERT INTO approval_steps (approval_request_id, quotation_id, level, required_role, status, approver_id, approver_name, assigned_at, comments, sla_deadline)
INSERT INTO fulfillment_plans (quotation_id, status, total_shipping_cost, shipment_count, created_at)
INSERT INTO fulfillment_splits (fulfillment_plan_id, quotation_id, warehouse_id, product_id, quantity, is_backorder, estimated_cost, shipment_group, status)
INSERT INTO invoices (invoice_number, quotation_id, customer_id, invoice_type, amount, status, due_date, paid_at, delivery_status, created_at)
INSERT INTO subscriptions (customer_id, quotation_id, quotation_line_id, plan_name, cycle, start_date, next_bill_date, amount, quantity, status, created_at)
INSERT INTO billing_schedules (subscription_id, quotation_line_id, billing_date, amount, status, proration_factor, proration_note, invoice_id)
INSERT INTO deal_health_flags (quotation_id, flag_type, severity, description, detected_at, resolved, resolved_at)
INSERT INTO negotiation_messages (quotation_id, sender_role, sender_name, message, line_reference_id, counter_discount_percent, requested_delivery_date, created_at)
